    (DEST/'result-summary.json').write_text(json.dumps(summary,indent=2)+'\n');files.add(PREFIX+'result-summary.json')
    old=baseline.decode();assert 'RESEARCH NOTEBOOK · 109' in old
    checkpoint_title='Cluster-assisted search discovers a checked incidence proof' if accepted else 'Cluster-assisted search finds an incidence candidate'
    panel='<section class="panel" id="fixed-family-search"><h2>Checkpoint 110 · '+checkpoint_title+'</h2><p>The fixed pool produces '+math(24)+' candidate proof rows in '+math(21)+' new placements, with '+math(0)+' backtracks, within the original budget. '+assertion+' <a href="fixed-family-search/reader.html?v=20261012-ffs1#reader">Inspect the actual colored tiles, formulas, English and controls</a>.</p><p>This is automatic recomposition of existing lemma families. No RL training, new lemma discovery or universal Wang-system claim is made.</p></section>\n'
    anchor='<section class="panel" id="family-pool-audit">';assert old.count(anchor)==1
    updated=old.replace('RESEARCH NOTEBOOK · 109','RESEARCH NOTEBOOK · 110',1).replace(anchor,panel+anchor,1)
